import java.lang.reflect.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Kalkulator k = new Kalkulator();
        Method m = Kalkulator.class.getMethod("bagi", int.class, int.class);
        System.out.println(m.invoke(k, 10, 2));
        try {
            m.invoke(k, 10, 0);
        } catch (InvocationTargetException e) {
            System.out.println("Penyebab: " + e.getCause().getClass().getSimpleName());
        }
    }
}

class Kalkulator {
    public int bagi(int a, int b) {
        return a / b;
    }
}

