class Todo implements Comparable<Todo> {
    private final int id;
    private String judul;
    private boolean selesai;
    static int jumlahDibuat;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
        jumlahDibuat++;
    }

    public int getId() {
        return id;
    }

    public String getJudul() {
        return judul;
    }

    public boolean isSelesai() {
