import java.lang.reflect.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Hitung h = new Hitung();
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(" ");
            int a = Integer.parseInt(d[1]);
            int b = Integer.parseInt(d[2]);
            try {
                Method m = Hitung.class.getMethod(d[0], int.class, int.class);
                System.out.println(m.invoke(h, a, b));
            } catch (NoSuchMethodException e) {
                System.out.println("perintah tidak dikenal: " + d[0]);
            }
        }
    }
}

class Hitung {
    public int tambah(int a, int b) {
        return a + b;
    }

    public int kurang(int a, int b) {
        return a - b;
    }

    public int kali(int a, int b) {
        return a * b;
    }
}
